sys_script_include.script:
var SportsHallAvailabilityAjax = Class.create();
SportsHallAvailabilityAjax.prototype = 
    Object.extendsObject(AbstractAjaxProcessor, {

    checkAvailability: function() {
        var hallId = this.getParameter('sysparm_hall_id');
        var startDate = this.getParameter('sysparm_start_date');
        var endDate = this.getParameter('sysparm_end_date');

        var gr = new GlideRecord(
            'x_1954179_sports_0_sports_hall_booking'
        );
        gr.addQuery('sports_hall', hallId);
        gr.addQuery('status', 'Approved');

        // Check for overlapping bookings
        gr.addQuery('start_date', '<', endDate);
        gr.addQuery('end_date', '>', startDate);
        gr.query();

        if (gr.next()) {
            return 'unavailable';
        }
        return 'available';
    },

    type: 'SportsHallAvailabilityAjax'
});
